import os
from pathlib import Path

DEFAULT_LOG_PATH = "/workspace/file-watcher-daemon/events.log"


def _log_path():
    return os.environ.get("LOG_PATH", DEFAULT_LOG_PATH)


def log_event(msg):
    path = Path(_log_path())
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(msg + "\n")

